    @classmethod
    async def get_all_supplier_locations(cls) -> List[dict]:
        all_suppliers = await cls.find(cls.deleted_at == None).to_list()

        supplier_data = []
        for supplier in all_suppliers:
            if supplier.supplier_locations:
