        ).to_list()

    @classmethod
    async def get_all_recitation_texts_by_collection_id(
        cls, 
        collection_id: str, 
        language: str, 
        search: Optional[str] = None, 
        skip: int = 0, 
        limit: int = 10
    ) -> Tuple[List["Text"], int]:

