            update={"$pull": {"rules": rule_id}}
        )
        logger.info(rst)
        rst = await app.state.engine.update_many(
            Event, {"rules": {"$elemMatch": {"$eq": rule_id}}},
            update={"$pull": {"rules": rule_id}}
        )
        # clean record resultInRecord
        logger.info(rst)
        rst = await app.state.engine.delete_many(Result, Result.rule == rule_id)
        logger.info(rst)

