    @classmethod
    async def delete_abilities(cls, item_data: dict, characteristic: str, unit: int, count: int, userid: Union[int, str]):

        from bot.models.user import User
        user_obj = None
        try:
            uid = int(userid)
            user_obj = await User.find_one(User.userid == uid)
            if not user_obj:
                user_obj = await User(userid=uid).insert()
        except Exception:
            try:
                user_obj = await User.find_one(User.id == ObjectId(userid))
            except Exception:
                pass
        if not user_obj:
            return False

        need_char = unit * count
        find_item = await cls.find_one({"owner": uid, "items_data": item_data})
        if not find_item:
            return False, {'ost': need_char}

        if 'abilities' not in find_item.items_data or not isinstance(find_item.items_data['abilities'], dict):
            find_item.items_data['abilities'] = {}
        if characteristic not in find_item.items_data['abilities']:
            from bot.modules.items.item import get_item_endurance_max, get_data
            if characteristic == 'endurance':
                max_val = get_item_endurance_max(find_item.items_data)
                if max_val is None:
                    item_static = get_data(find_item.items_data.get('item_id', ''))
                    max_val = item_static.get('endurance_max', 100) if isinstance(item_static, dict) else 100
                find_item.items_data['abilities']['endurance'] = max_val
            else:
                find_item.items_data['abilities'][characteristic] = 0

        durability = find_item.items_data['abilities'][characteristic]
        if durability <= 0:
            return False, {'ost': need_char}
        total = durability * find_item.count
        if total < need_char:
            return False, {'ost': need_char - total}

        delete_count = need_char // durability
        remainder = need_char % durability
        set_value = None
        if remainder > 0:
            if delete_count >= find_item.count:
                return False, {'ost': 0}
            set_value = durability - remainder

        return True, {
            'delete_count': delete_count,
            'set': set_value
        }

    @classmethod
    async def downgrade(cls, userid: Union[int, str], item: dict, characteristic: str, amount: int):

        from bot.models.user import User
        user_obj = None
        try:
            uid = int(userid)
            user_obj = await User.find_one(User.userid == uid)
            if not user_obj:
                user_obj = await User(userid=uid).insert()
        except Exception:
            try:
                user_obj = await User.find_one(User.id == ObjectId(userid))
            except Exception:
                pass
        if not user_obj:
            return False

        from bot.modules.logs import log
        doc = await cls.find_one({"owner": uid, "items_data": item})
        if not doc:
            return {'status': False, 'action': 'unit', 'difference': amount}

        if 'abilities' not in doc.items_data or not isinstance(doc.items_data['abilities'], dict):
            doc.items_data['abilities'] = {}
        if characteristic not in doc.items_data['abilities']:
            from bot.modules.items.item import get_item_endurance_max, get_data
            if characteristic == 'endurance':
                max_val = get_item_endurance_max(doc.items_data)
                if max_val is None:
                    item_static = get_data(doc.items_data.get('item_id', ''))
                    max_val = item_static.get('endurance_max', 100) if isinstance(item_static, dict) else 100
                doc.items_data['abilities']['endurance'] = max_val
            else:
                doc.items_data['abilities'][characteristic] = 0

        durability = doc.items_data['abilities'][characteristic]
        if durability <= 0:
            return {'status': False, 'action': 'unit', 'difference': amount}
        count = doc.count
        total_durability = durability * count

        if total_durability < amount:
            return {'status': False, 'action': 'unit', 'difference': amount - total_durability}

        full_remove = amount // durability
        remainder = amount % durability
        actions = []

        async with Transaction():
            if full_remove > 0:
                await cls.remove(userid, doc.items_data['item_id'], full_remove, doc.items_data['abilities'])
                actions.append({'delete_count': full_remove})

            if remainder > 0:
                await cls.remove(userid, doc.items_data['item_id'], 1, doc.items_data['abilities'])
                new_abilities = dict(doc.items_data['abilities'])
                new_abilities[characteristic] = durability - remainder
                await cls.add(userid, doc.items_data['item_id'], 1, new_abilities)
                actions.append({'edit': durability - remainder})

        log(f'DowngradeItem {userid} {item} {characteristic} {amount} {actions}', 0, 'DowngradeItem')
        return {'status': True, 'action': 'deleted_edited', 'details': actions}

    # Accessory Logic Methods
    @classmethod
    async def find_accessory(cls, dino_id: ObjectId, acc_type: Optional[str] = None) -> List["Item"]:
        items = await cls.find({"owner": str(dino_id)}).to_list()
        if acc_type:
            return [i for i in items if i.data['type'] == acc_type]
        return items

    @classmethod
    async def downgrade_accessory(cls, 
            dino_id: ObjectId, 
            item_id: str, 
            max_unit: int = 2
        ) -> bool:

        from bot.modules.notifications import dino_notification
        from bot.modules.items.item import get_item_endurance_max, get_data
        item = await cls.find_one({"owner": str(dino_id), "items_data.item_id": item_id})
        if item:
            if 'abilities' not in item.items_data or not isinstance(
                item.items_data['abilities'], dict):
                item.items_data['abilities'] = {}
            if 'endurance' not in item.items_data['abilities']:
                max_end = get_item_endurance_max(item.items_data)
                if max_end is None:
                    item_static = get_data(item_id)
                    max_end = item_static.get('endurance_max', 100) if isinstance(item_static, dict) else 100
                item.items_data['abilities']['endurance'] = max_end

            if 'endurance' in item.items_data['abilities']:
                num = randint(0, max_unit)
                async with Transaction():
                    item.items_data['abilities']['endurance'] -= num
                    if item.items_data['abilities']['endurance'] <= 0:
                        await item.delete()
                        await dino_notification(dino_id, 
                        'broke_accessory', item_id=item_id)
                    else:
                        await item.save()
                return True
        return False

