    created: datetime = Field(default=datetime.utcnow())
    updated: datetime = Field(default=datetime.utcnow())
    auth_config: List[AuthConfig]
    role: str = Roles.Default.value
    domain: str
    scopes: List[str] = []

    def allowed_scopes(
        self,
        scopes: List[str]
    ) -> Generator[str, None, None]:
        for scope in self.scopes:
            if scope in scopes:
                yield scope
        return None

    @classmethod
    async def by_user(
        cls: Type['IdpRoleConfig'],
        database: AIOEngine,
        user_information: UserInformation,
        domain: str = 'default'
    ) -> List['IdpRoleConfig']:
        groups = user_information.groups
        username = user_information.username
        return await cls.by_user_groups(database, username, groups, domain)

    @classmethod
    async def by_user_groups(
        cls: Type['IdpRoleConfig'],
        database: AIOEngine,
        user: str,
        groups: List[str],
        domain: str
    ) -> List['IdpRoleConfig']:
        role_configs = await cls.get(database, domain)
        roles: List[IdpRoleConfig] = []
        if user and groups and role_configs:
            role_config: Optional[IdpRoleConfig] = None
            async for role_config in role_configs:
                for auth_config in role_config.auth_config:
                    if await cls.check_auth_config(auth_config, groups, user):
                        roles.append(role_config)
        return roles

    @classmethod
    async def check_auth_config(
        cls: type,
        auth_config: AuthConfig,
        groups: List[str],
        user: str
    ):
        if str(auth_config.auth_type) == str(AuthType.GROUP):
            if auth_config.name in groups:
                return True
        elif auth_config.auth_type == AuthType.USER:
            if auth_config.name == user:
                return True
        return False

    @classmethod
    async def get(
        cls: Type['IdpRoleConfig'],
        database: AIOEngine,
        domain: str
    ) -> Optional[AIOCursor['IdpRoleConfig']]:
        if domain:
            return database.find(
                cls,
                cls.domain == domain, cls.enabled == True  # noqa
            )
        return None

from typing import Any, ClassVar, Generic, TypeVar, Union

import odmantic
from pydantic.annotated_handlers import GetCoreSchemaHandler
from pydantic.json_schema import JsonSchemaValue
from pydantic_core import CoreSchema, core_schema

T = TypeVar("T", str, bytes)


def _display(value: T) -> str:
    if isinstance(value, bytes):
        return b"..." if value else b""
    return f"{value[:10]}..." if value else ""


class LongField(Generic[T]):
    _inner_schema: ClassVar[CoreSchema]
    _error_kind: ClassVar[str]

    @classmethod
    def __get_pydantic_core_schema__(
        cls, source: type[Any], handler: GetCoreSchemaHandler
    ) -> CoreSchema:
        def serialize(
            value: "LongField[T]", info: core_schema.SerializationInfo
        ) -> Union[str, "LongField[T]"]:
            if info.mode == "json":
                return _display(value.get_value())
            else:
                return value

        def get_json_schema(
            _core_schema: CoreSchema, handler: GetCoreSchemaHandler
        ) -> JsonSchemaValue:
            json_schema = handler(cls._inner_schema)
            return json_schema

        json_schema = core_schema.no_info_after_validator_function(
            source,  # construct the type
            cls._inner_schema,
        )

        def get_schema() -> CoreSchema:
            return core_schema.json_or_python_schema(
                python_schema=core_schema.union_schema(
                    [
                        core_schema.is_instance_schema(source),
                        json_schema,
                    ],
                    custom_error_type=cls._error_kind,
                ),
                json_schema=json_schema,
                serialization=core_schema.plain_serializer_function_ser_schema(
                    serialize,
                    info_arg=True,
                    return_schema=core_schema.str_schema(),
                    when_used="json",
                ),
            )

        return get_schema()

    def __init__(self, value: T):
        self._value = value

    def get_value(self) -> T:
        return self._value

    def __repr__(self) -> str:
        return '""'  # Always return an empty string representation

    def __str__(self) -> str:
        return _display(self._value)


class LongStr(LongField[str]):
    """A string that displays '...' instead of the full content in logs or tracebacks."""

    _inner_schema: ClassVar[CoreSchema] = core_schema.str_schema()
    _error_kind: ClassVar[str] = "string_type"


class LongBytes(LongField[bytes]):
    """Wrap byte streams to avoid messy output."""

    _inner_schema: ClassVar[CoreSchema] = core_schema.bytes_schema()
    _error_kind: ClassVar[str] = "bytes_type"


class FilePlaceholder(odmantic.EmbeddedModel):
    content: LongBytes = odmantic.Field(
        default=b"", json_schema_extra={"exclude": True}
    )

