@simstack_model
class OptimizationStepInput(EmbeddedModel):
    field_name: str = "OptimizationStepInput"
    basis_set: BasisSet = Field(default_factory=BasisSet)
    functional: Functional = Field(default_factory=Functional)
    max_optimization_iterations: int = Field(
        100,
        json_schema_extra={"description": "Maximum number of geometry optimization iterations"},
    )
    max_scf_iterations: int = Field(
        100,
        json_schema_extra={"description": "Maximum number of SCF cycles"},
    )

    @model_validator(mode="before")
    @classmethod
    def ensure_fieldname(cls, data):
        if isinstance(data, dict) and "field_name" not in data:
            data["field_name"] = cls.__name__
        return data


@simstack_model
class PreOptimizerInput(Model):
    field_name: str = "PreOptimizerInput"
    dftb_opt: bool = Field(
        False,
        json_schema_extra={"title": "DFTB pre-optimization"},
    )
    max_dftb_iterations: int = Field(
        100,
        json_schema_extra={
            "title": "Max DFTB iterations",
            "description": "Maximum DFTB geometry optimization steps",
        },
    )
    steps: List[OptimizationStepInput] = Field(default_factory=list)

    @model_validator(mode="before")
    @classmethod
    def ensure_fieldname(cls, data):
        if isinstance(data, dict) and "field_name" not in data:
            data["field_name"] = cls.__name__
        return data

    @classmethod
    def json_schema(cls, recursive=True):
        schema = cleaned_json_schema(cls)
        schema["title"] = cls.__name__
        props = schema["properties"]
        max_dftb = props.pop("max_dftb_iterations", None)
        schema.setdefault("dependencies", {})["dftb_opt"] = {
            "oneOf": [
                {"properties": {"dftb_opt": {"const": False}}},
                {
                    "properties": {
                        "dftb_opt": {"const": True},
                        "max_dftb_iterations": max_dftb,
                    }
                },
            ]
        }
        return schema

    @classmethod
    def ui_schema(cls):
        ui = generate_ui_schema(cls)
        ui["field_name"] = {"ui:widget": "hidden"}
        ui["dftb_opt"] = {
            "ui:widget": "checkbox",
            "ui:title": "DFTB pre-optimization",
        }
        ui.setdefault("max_dftb_iterations", {})["ui:condition"] = {"dftb_opt": True}
        return ui


def _dftb_preopt_input(qm_input: QMInput, max_dftb_iterations: int) -> DftbInput:
    """Build DftbInput for geometry pre-optimization."""
    return DftbInput(
        optimization=True,
        charge=qm_input.charge,
        multiplicity=qm_input.multiplicity,
        compute_gradients=True,
        max_optimization_steps=max_dftb_iterations,
    )


def _qm_input_for_step(
    qm_input: QMInput,
    step: OptimizationStepInput,
    molecule: Molecule,
) -> QMInput:
    """Copy QMInput for one Psi4 DFT optimization step, applying step overrides.

    Geometry optimization is always enabled, even when the template ``qm_input``
    has ``optimization=False``. Overrides are applied after the copy so they
    work even if ``from_model`` ignores keyword arguments.
    """
    copied = QMInput.from_model(qm_input, optimization=True, frequencies=False)
    copied.optimization = True
    copied.frequencies = False
    copied.field_name = "QMInput"
    copied.non_standard_parameters = True
    copied.molecule = molecule
    copied.basis_set = step.basis_set
    copied.functional = step.functional
    copied.max_optimization_iterations = step.max_optimization_iterations
    copied.max_scf_iterations = step.max_scf_iterations
    return copied


def _child_qm_result(calc_result) -> Tuple[Optional[QMResult], Optional[str]]:
    """Return (qm_result, error_message). error_message is None on success."""
    if calc_result is None:
        return None, "child node returned no result"
    if isinstance(calc_result, SimstackResult):
        if calc_result.status != TaskStatus.COMPLETED:
            return None, calc_result.error_message or "child node failed"
        for name in ("qm_result", "psi4_result"):
            value = getattr(calc_result, name, None)
            if isinstance(value, QMResult):
                return value, None
        return None, "child node returned no QMResult"
    if isinstance(calc_result, QMResult):
        return calc_result, None
    for name in ("qm_result", "psi4_result"):
        value = getattr(calc_result, name, None)
        if isinstance(value, QMResult):
            return value, None
    return None, f"unexpected child result type: {type(calc_result)}"


def _append_step_row(
    table: SimpleTable,
    step_name: str,
    basis_set: str,
    functional: str,
    qm_result: Optional[QMResult],
    node_runner,
) -> None:
    energy = None if qm_result is None else qm_result.final_energy
    converged = (
        None
        if qm_result is None or qm_result.optimization_converged is None
        else str(qm_result.optimization_converged)
    )
    table.add_row(
        {
            "step": step_name,
            "basis_set": basis_set,
            "functional": functional,
            "energy": energy,
            "optimization_converged": converged,
        }
    )
    node_runner.info(
        f"step={step_name} basis_set={basis_set} functional={functional} "
        f"energy={energy} optimization_converged={converged}"
    )


@node
async def multistep_optimizer(
    qm_input: QMInput, preopt: PreOptimizerInput, **kwargs
) -> SimstackResult:
    """Run an optional DFTB pre-optimization followed by sequential Psi4 optimizations.

    Each Psi4 step uses the previous step's final geometry. Charge, solvent, and
    other QMInput settings are copied from ``qm_input``; each step overrides
    basis set, functional, and iteration limits.

    Parameters:
        qm_input (QMInput): Molecule and shared QM settings used as the copy template.
        preopt (PreOptimizerInput): DFTB toggle, max DFTB iterations, and ordered Psi4 steps.

    Called Nodes:
        dftb_calculator
        psi4_calculator

    SimstackResult:
        qm_result (QMResult): Result of the last successful step.
        step_table (SimpleTable): Per-step basis, functional, energy, and convergence.
    """
    node_runner = kwargs.get("node_runner")
    steps = list(preopt.steps or [])
    if not preopt.dftb_opt and not steps:
        return node_runner.fail(
            "PreOptimizerInput has no steps and dftb_opt is False"
        )

    qm_input.optimization = True
    molecule = qm_input.molecule
    last_result: Optional[QMResult] = None
    step_table = SimpleTable(name="Multistep optimizer")
    step_table.add_column("step", "string")
    step_table.add_column("basis_set", "string")
    step_table.add_column("functional", "string")
    step_table.add_column("energy", "number")
    step_table.add_column("optimization_converged", "string")
    tolerate_failure = bool(getattr(qm_input, "tolerate_failure", False))

    if preopt.dftb_opt:
        opts = _dftb_preopt_input(qm_input, preopt.max_dftb_iterations)
        node_runner.info(
            f"Starting DFTB pre-optimization "
            f"(max_dftb_iterations={preopt.max_dftb_iterations})"
        )
        try:
            calc_result = await dftb_calculator(molecule, opts, **kwargs)
        except Exception as exc:
            error = str(exc)
            qm_result = None
        else:
            qm_result, error = _child_qm_result(calc_result)
        if error:
            if tolerate_failure:
                node_runner.warning(f"DFTB pre-optimization failed: {error}")
            else:
                return node_runner.fail(f"DFTB pre-optimization failed: {error}")
        else:
            last_result = qm_result
            if qm_result.final_structure is not None:
                molecule = qm_result.final_structure
            _append_step_row(step_table, "dftb", "", "GFN2-xTB", qm_result, node_runner)
            node_runner.info("DFTB pre-optimization finished")

    for index, step in enumerate(steps, start=1):
        step_name = f"psi4-{index}"
        basis_name = step.basis_set.basis_set.value
        functional_name = step.functional.functional.value
        node_runner.info(
            f"Starting {step_name}: basis={basis_name}, functional={functional_name}, "
            f"optimization=True, "
            f"max_optimization_iterations={step.max_optimization_iterations}, "
            f"max_scf_iterations={step.max_scf_iterations}"
        )
        current_input = _qm_input_for_step(qm_input, step, molecule)
        try:
            calc_result = await psi4_calculator(current_input, **kwargs)
        except Exception as exc:
            error = str(exc)
            qm_result = None
        else:
            qm_result, error = _child_qm_result(calc_result)
        if error:
            if tolerate_failure:
                node_runner.warning(f"{step_name} failed: {error}")
                break
            return node_runner.fail(f"{step_name} failed: {error}")
        last_result = qm_result
        if qm_result.final_structure is None:
            node_runner.warning(
                f"{step_name} returned no final_structure; reusing previous geometry"
            )
        else:
            molecule = qm_result.final_structure
        _append_step_row(
            step_table, step_name, basis_name, functional_name, qm_result, node_runner
        )

    if last_result is None:
        return node_runner.fail("multistep_optimizer produced no QMResult")

    node_runner.qm_result = last_result
    node_runner.step_table = step_table
    return node_runner.succeed()

from odmantic import Model, EmbeddedModel, Field
from datetime import datetime, UTC
from typing import Literal
from pydantic import BaseModel
import uuid


class MetadataField(BaseModel):
    key: str
    label: str
    type: Literal["number", "boolean", "literal", "multi_literal", "rating", "counter", "duration", "text"]
    options: list[str] | None = None
    min: float | None = None
    max: float | None = None
    unit: str | None = None
    required: bool = False
    active: bool = True


class SchemaNode(EmbeddedModel):
    id: str | None = None
    name: str
    parent_id: str | None = None
    children: list[str] = Field(default_factory=list)
    metadata_schema: list[MetadataField] = Field(default_factory=list)
    is_active: bool = True


class MasterSchema(Model):
    user_id: str | None = None
    version: int = 1
    nodes: list[SchemaNode] = Field(default_factory=list)
    created_at: datetime = Field(default_factory=lambda: datetime.now(tz=UTC))
    updated_at: datetime = Field(default_factory=lambda: datetime.now(tz=UTC))

    def get_node(self, name: str) -> SchemaNode | None:
        for node in self.nodes:
            if node.name == name:
                return node
        return None

    def get_node_by_id(self, node_id: str) -> SchemaNode | None:
        for node in self.nodes:
            if node.id == node_id:
                return node
        return None

    def get_path(self, name: str) -> list[str]:
        path = []
        visited = set()
        current = self.get_node(name)
        while current and current.name not in visited:
            visited.add(current.name)
            path.insert(0, current.name)
            if current.parent_id:
                current = self.get_node_by_id(current.parent_id)
            else:
                break
        return path

    def add_node(self, parent_name: str | None, new_node_name: str) -> SchemaNode:
        if self.get_node(new_node_name):
            return self.get_node(new_node_name)

        parent = None
        if parent_name:
            parent = self.get_node(parent_name)
            if parent is None:
                raise ValueError(f"Parent node '{parent_name}' does not exist")

        new_node = SchemaNode(
            id=str(uuid.uuid4()),
            name=new_node_name,
            parent_id=parent.id if parent else None,
            children=[],
        )

        if parent:
            if new_node.id not in parent.children:
                parent.children.append(new_node.id)

        self.nodes.append(new_node)
        self.updated_at = datetime.now(tz=UTC)
        return new_node

    def find_or_create_node(self, path: list[str]) -> str:
        if not path:
            raise ValueError("Path cannot be empty")
        parent_node = None
        for node_name in path:
            existing = self.get_node(node_name)
            if not existing:
                parent_id = parent_node.id if parent_node else None
                new_node = SchemaNode(
                    id=str(uuid.uuid4()),
                    name=node_name,
                    parent_id=parent_id,
                    children=[],
                )
                if parent_node:
                    if new_node.id not in parent_node.children:
                        parent_node.children.append(new_node.id)
                self.nodes.append(new_node)
                parent_node = new_node
            else:
                parent_node = existing
        return parent_node.id if parent_node else ""

    def get_active_node(self, name: str) -> SchemaNode | None:
        for node in self.nodes:
            if node.name == name and node.is_active:
                return node
        return None

    def get_active_node_by_id(self, node_id: str) -> SchemaNode | None:
        for node in self.nodes:
            if node.id == node_id and node.is_active:
                return node
        return None

    def get_all_active_nodes(self) -> list[SchemaNode]:
        return [node for node in self.nodes if node.is_active]

    def get_active_children(self, node_id: str) -> list[str]:
        node = self.get_node_by_id(node_id)
        if not node:
            return []
        return [
            child_id
            for child_id in node.children
            if self.get_active_node_by_id(child_id)
        ]

    def update_node_name(self, old_name: str, new_name: str) -> list[SchemaNode]:
        updated = []
        node = self.get_node(old_name)
        if node:
            node.name = new_name
            self.updated_at = datetime.now(tz=UTC)
            updated.append(node)
        return updated

    def update_node_name_by_id(self, node_id: str, new_name: str) -> list[SchemaNode]:
        updated = []
        node = self.get_node_by_id(node_id)
        if node:
            node.name = new_name
            self.updated_at = datetime.now(tz=UTC)
            updated.append(node)
        return updated

    def inactivate_node(self, node_name: str) -> SchemaNode | None:
        node = self.get_node(node_name)
        if node:
            node.is_active = False
            self.updated_at = datetime.now(tz=UTC)
        return node

    def inactivate_node_by_id(self, node_id: str) -> SchemaNode | None:
        node = self.get_node_by_id(node_id)
        if node:
            node.is_active = False
            self.updated_at = datetime.now(tz=UTC)
        return node

    def activate_node(self, node_name: str) -> SchemaNode | None:
        node = self.get_node(node_name)
        if node:
            node.is_active = True
            self.updated_at = datetime.now(tz=UTC)
        return node

    def activate_node_by_id(self, node_id: str) -> SchemaNode | None:
        node = self.get_node_by_id(node_id)
        if node:
            node.is_active = True
            self.updated_at = datetime.now(tz=UTC)
        return node

    def move_node(self, node_name: str, new_parent_name: str | None) -> SchemaNode:
        node = self.get_node(node_name)
        if not node:
            raise ValueError(f"Node '{node_name}' does not exist")

        old_parent = None
        if node.parent_id:
            old_parent = self.get_node_by_id(node.parent_id)

        new_parent = None
        if new_parent_name:
            new_parent = self.get_node(new_parent_name)
            if new_parent is None:
                raise ValueError(f"New parent node '{new_parent_name}' does not exist")
            if self._is_descendant(node.id, new_parent.id):
                raise ValueError("Cannot move a node into its own descendant")

        if old_parent and node.id in old_parent.children:
            old_parent.children.remove(node.id)

        node.parent_id = new_parent.id if new_parent else None

        if new_parent and node.id not in new_parent.children:
            new_parent.children.append(node.id)

        self.updated_at = datetime.now(tz=UTC)
        return node

    def _is_descendant(self, ancestor_id: str, descendant_id: str) -> bool:
        if ancestor_id == descendant_id:
            return True
        node = self.get_node_by_id(descendant_id)
        while node and node.parent_id:
            if node.parent_id == ancestor_id:
                return True
            node = self.get_node_by_id(node.parent_id)
        return False

import re
from enum import Enum, auto
from typing import AnyStr, List, Match, NamedTuple, Optional

from aiogram.types import Message
from aiogram.types.inline_keyboard import InlineKeyboardButton, InlineKeyboardMarkup
from odmantic import EmbeddedModel
from telethon.tl.custom import Button as TButton

from src import BOT
from src.types.chat import ChatId
from .text import random_parser

START_URL = f'https://t.me/{BOT.username}?start='
BUTTONS_TEXT_REGEXP = re.compile(
    # [Button name](type:argument:same)
    r'\[(.+?)]\((?:button|btn)?(?!http(?:s))(\w+|#)(?:(?:[:=])?(?:\s)?(?://)?(.*?)|)[:=]?(?:(?:\s)?(same|\^))?\)(?:\n)?'
)
BUTTON_CALLBACK_PATTERN = "{prefix}-{action}-{argument}-{chat_id}"
BUTTONS_CALLBACK_REGEXP = re.compile(
    r'(.*?)-(.*?)-(.*?)-(.*)'
)


class DefinedButtonType(Enum):
    smart = auto()
    callback = auto()
    start = auto()
    url = auto()


class RealButtonTypes(Enum):
    url = auto()
    callback = auto()


class DBButton(EmbeddedModel):
    name: str
    action: str
    argument: str


class DefinedButtonOptions(NamedTuple):
    cb_prefix: str
    type: DefinedButtonType
    argument_optional: bool


BUTTONS = {
    'url': DefinedButtonOptions('', type=DefinedButtonType.url, argument_optional=False)
}


class ButtonException(Exception):
    pass


class WrongButtonAction(ButtonException):
    def __init__(self, button_name, action):
        self.button_name = button_name
        self.action = action


class ButtonShouldHaveArgument(ButtonException):
    def __init__(self, button_name, action):
        self.button_name = button_name
        self.action = action


class TooMuchButtonsInRow(ButtonException):
    pass


BUTTONS_EXCEPTIONS = (
    WrongButtonAction,
    ButtonShouldHaveArgument,
    TooMuchButtonsInRow
)


class ButtonFabric(List[List[DBButton]]):
    """Represents a inline buttons of a message. Can be stored in the database.
    Contains a functions to parse and unparse buttons."""

    @staticmethod
    def test_button_before_saving(button_name: str, action, argument):
        """Raises a exception if button has a problem."""
        if action not in BUTTONS:
            raise WrongButtonAction(button_name=button_name, action=action)

        defined_button_options: DefinedButtonOptions = BUTTONS[action]
        if not defined_button_options.argument_optional and not argument:
            raise ButtonShouldHaveArgument(button_name=button_name, action=action)

    def parse_text(self, text: str) -> str:
        """Parses a text into buttons. Returns a text without buttons."""
        raw_buttons: List[Match[AnyStr]] = BUTTONS_TEXT_REGEXP.findall(text)
        for raw_button in raw_buttons:
            button_name: str = raw_button[0]
            action: str = raw_button[1]
            argument: str = raw_button[2]
            same_row: bool = bool(raw_button[3])

            self.test_button_before_saving(button_name, action, argument)
            self.add_button(button_name, action, argument, same_row=same_row)

        return BUTTONS_TEXT_REGEXP.sub('', text)

    def parse_message(self, message: Message) -> bool:
        """Parses a message with buttons. Returns if buttons are found"""
        if not message.reply_markup or not message.reply_markup.inline_keyboard:
            # There is no inline buttons in message
            return False

        for row in message.reply_markup.inline_keyboard:
            for idx, button in enumerate(row):
                button_name: str = button['text']
                same_row: bool = idx > 0

                if button.callback_data or button.url and button.url.startswith(START_URL):
                    string: str = button['url'].split(START_URL)[1] if 'url' in button else button['callback_data']

                    if not (data := BUTTONS_CALLBACK_REGEXP.search(string)):
                        # A button from older SophieBot syntax or other bots, let's skip it.
                        continue

                    data: Match[AnyStr]
                    action = data[2]
                    argument = data[3]
                elif button.url:
                    # A simple url button
                    action = 'url'
                    argument = button['url']
                else:
                    # A wrong button type, let's skip it
                    continue

                self.test_button_before_saving(button_name, action, argument)
                self.add_button(button_name, action, argument, same_row=same_row)

        return True

    def add_button(
            self,
            button_name: str,
            action: str,
            argument: Optional[str],
            same_row: bool = False
    ):
        # Name url https://google.com
        # Name smart test_cb
        button = DBButton(name=button_name, action=action, argument=argument)

        if not same_row or len(self) < 1:
            self.append([button])
        else:
            self[-1].append(button)

    @staticmethod
    def get_smart_button(button: DBButton, argument: Optional[str] = None):
        url: str = START_URL + argument or button['argument']
        return button['name'], RealButtonTypes.url, url

    @staticmethod
    def get_callback_button(button: DBButton, argument: Optional[str] = None):
        return button['name'], RealButtonTypes.callback, argument or button['argument']

    def get_callback(self, button: DBButton, options: DefinedButtonOptions, chat_id: ChatId):
        return BUTTON_CALLBACK_PATTERN.format(
            prefix=options.cb_prefix,
            action=button['action'],
            argument=button['argument'],
            chat_id=chat_id
        )

    def unparse_button(self, button: dict, is_pm: bool, chat_id: ChatId) -> (str, RealButtonTypes, str):
        options = BUTTONS[button['action']]
        callback_data = self.get_callback(button, options, chat_id)

        if options.type is DefinedButtonType.url:
            return button['name'], RealButtonTypes.url, button['argument']

        elif options.type is DefinedButtonType.callback:
            return self.get_callback_button(button)

        # Here is buttons a little more complicated
        elif options.type is DefinedButtonType.start:
            return self.get_smart_button(button, argument=callback_data)

        elif options.type is DefinedButtonType.smart:
            if is_pm:
                return self.get_callback_button(button, argument=callback_data)
            else:
                return self.get_smart_button(button, argument=callback_data)

    def unparse_to_text(self) -> str:
        """Unparses buttons to text. Uses the most modern buttons syntax."""
        result = ''

        for row in self:
            for idx, button in enumerate(row):
                text = f"[{button['name']}]({button['action']}"
                if button['argument']:
                    text += f":{button['argument']}"
                if idx != 0:
                    # Same row
                    text += ':^'
                text += ')\n'
                result += text

        return result

    @staticmethod
    def apply_random_name(button_name: str) -> str:
        return random_parser(button_name)

    def aiogram(self, chat_id: ChatId, is_pm: bool = False) -> InlineKeyboardMarkup:
        """Unparses buttons for aiorgam send_message function"""
        markup = InlineKeyboardMarkup()

        for row in self:
            for idx, button in enumerate(row):
                button_name, button_type, argument = self.unparse_button(button, is_pm, chat_id)

                kwargs = {}
                if button_type is RealButtonTypes.url:
                    kwargs['url'] = argument
                elif button_type is RealButtonTypes.callback:
                    kwargs['callback_data'] = argument

                button = InlineKeyboardButton(self.apply_random_name(button_name), **kwargs)

                if idx > 0:
                    markup.insert(button)
                else:
                    markup.add(button)

        return markup

    def telethon(self, chat_id: ChatId, is_pm: bool = False) -> List[List[TButton]]:
        rows = []
        for row in self:
            for idx, button in enumerate(row):
                button_name, button_type, argument = self.unparse_button(button, is_pm, chat_id)

                if button_type is RealButtonTypes.url:
                    button = TButton.url(button_name, argument)
                elif button_type is RealButtonTypes.callback:
                    button = TButton.inline(button_name, argument)

                if not idx > 0 or len(self) < 1:
                    rows.append([button])
                else:
                    rows[-1].append(button)

        return rows

