"""
Payroll Model for HR Bot System
Represents a payroll record for an employee for a specific pay period.
"""

from beanie import Document
from pydantic import Field, field_validator, model_validator
from typing import Optional, List
from datetime import datetime, date
from pymongo import IndexModel
from bson import ObjectId
from decimal import Decimal, InvalidOperation
from bson.decimal128 import Decimal128
import logging
import re

logger = logging.getLogger(__name__)

# Payroll status enum values
PAYROLL_STATUS = {"pending", "processed", "completed"}


class Payroll(Document):
    """
    Payroll document model for HR management.

    Represents a payroll record for an employee for a specific pay period.
    Stores salary information including base salary, deductions, allowances, and net salary.
    """
    payroll_id: str  # Unique identifier (e.g., "PAY001", "PAY002")
    employee_id: ObjectId  # Reference to Employee
    pay_period: str  # Pay period in YYYY-MM format (e.g., "2025-01")
    base_salary: Decimal  # Base salary amount (positive number)
    deductions: Optional[List[dict]] = Field(default_factory=list)  # List of deduction items: [{"description": "Tax", "amount": 5000.00}]
    allowances: Optional[List[dict]] = Field(default_factory=list)  # List of allowance items: [{"description": "Transport", "amount": 500.00}]
    net_salary: Decimal  # Net salary amount (positive number, manually entered by boss)
    payment_date: Optional[date] = None  # Payment date (YYYY-MM-DD)
    status: str = Field(default="pending")  # Payroll status: "pending" | "processed" | "completed"
    creator_id: ObjectId  # Reference to Employee (boss) who created the payroll record
    created_at: datetime = Field(default_factory=datetime.now)
    updated_at: datetime = Field(default_factory=datetime.now)
    deleted_at: Optional[datetime] = None

    @field_validator('pay_period')
    @classmethod
    def validate_pay_period(cls, v: str) -> str:
        """Validate pay period format (YYYY-MM) and month validity"""
        if not v or not v.strip():
            raise ValueError("⚠️ 薪資期間不能為空")

        v = v.strip()
        # Check format: YYYY-MM
        period_pattern = r'^\d{4}-\d{2}$'
        if not re.match(period_pattern, v):
            raise ValueError("⚠️ 薪資期間格式錯誤，應為 YYYY-MM 格式（例如：2025-01）")

        # Check if month is valid (01-12)
        try:
            year, month = v.split('-')
            month_int = int(month)
            if month_int < 1 or month_int > 12:
                raise ValueError("⚠️ 月份必須在 01-12 之間")
        except ValueError as e:
            if "月份必須" in str(e):
                raise
            raise ValueError("⚠️ 薪資期間格式錯誤，應為 YYYY-MM 格式（例如：2025-01）")

        return v

    @field_validator('base_salary', 'net_salary', mode='before')
    @classmethod
    def validate_salary_amount(cls, v) -> Decimal:
        """Validate salary amounts are positive numbers"""
        # Handle Decimal128 from MongoDB
        if isinstance(v, Decimal128):
            v = v.to_decimal()
        elif isinstance(v, str):
            try:
                v = Decimal(str(v).replace(",", "").replace("$", "").replace("¥", ""))
            except (InvalidOperation, ValueError):
                raise ValueError("⚠️ 薪資金額格式錯誤，應為正數")
        elif not isinstance(v, Decimal):
            try:
                v = Decimal(str(v))
            except (InvalidOperation, ValueError):
                raise ValueError("⚠️ 薪資金額格式錯誤，應為正數")

        if v <= 0:
            raise ValueError("⚠️ 薪資金額必須大於零")

        return v

    @field_validator('status')
    @classmethod
    def validate_status(cls, v: str) -> str:
        """Validate status is one of: pending, processed, completed"""
        if v not in PAYROLL_STATUS:
            raise ValueError(f"⚠️ 狀態必須是以下之一: {', '.join(PAYROLL_STATUS)}")
        return v

    @model_validator(mode='after')
    def validate_deductions_and_allowances(self):
        """Validate deductions and allowances are properly formatted"""
        # Validate deductions
        if self.deductions:
            for deduction in self.deductions:
                if not isinstance(deduction, dict):
                    raise ValueError("⚠️ 扣減項目格式錯誤，應為字典格式")
                if "description" not in deduction or "amount" not in deduction:
                    raise ValueError("⚠️ 扣減項目必須包含 description 和 amount 欄位")
                try:
                    amount = Decimal(str(deduction["amount"]))
                    if amount <= 0:
                        raise ValueError("⚠️ 扣減金額必須大於零")
                    # Normalize amount to Decimal
                    deduction["amount"] = amount
                except (InvalidOperation, ValueError) as e:
                    if "大於零" in str(e):
                        raise
                    raise ValueError("⚠️ 扣減金額格式錯誤，應為正數")

        # Validate allowances
        if self.allowances:
            for allowance in self.allowances:
                if not isinstance(allowance, dict):
                    raise ValueError("⚠️ 津貼項目格式錯誤，應為字典格式")
                if "description" not in allowance or "amount" not in allowance:
                    raise ValueError("⚠️ 津貼項目必須包含 description 和 amount 欄位")
                try:
                    amount = Decimal(str(allowance["amount"]))
                    if amount <= 0:
                        raise ValueError("⚠️ 津貼金額必須大於零")
                    # Normalize amount to Decimal
                    allowance["amount"] = amount
                except (InvalidOperation, ValueError) as e:
                    if "大於零" in str(e):
                        raise
                    raise ValueError("⚠️ 津貼金額格式錯誤，應為正數")

        return self

    class Settings:
        name = "payroll_collection"
        indexes = [
            IndexModel(
                [("payroll_id", 1)],
                unique=True,
                partialFilterExpression={"deleted_at": {"$eq": None}}
            ),
            IndexModel(
                [("employee_id", 1)],
                partialFilterExpression={"deleted_at": {"$eq": None}}
            ),
            IndexModel(
                [("pay_period", 1)],
                partialFilterExpression={"deleted_at": {"$eq": None}}
            ),
            IndexModel(
                [("employee_id", 1), ("pay_period", 1)],
                unique=True,
                partialFilterExpression={"deleted_at": {"$eq": None}},
                name="employee_period_unique"
            ),
            IndexModel(
                [("status", 1)],
                partialFilterExpression={"deleted_at": {"$eq": None}}
            ),
            IndexModel(
                [("created_at", -1)],
                partialFilterExpression={"deleted_at": {"$eq": None}}
            ),
            IndexModel(
                [("creator_id", 1)],
                partialFilterExpression={"deleted_at": {"$eq": None}}
            )
        ]

    class Config:
        arbitrary_types_allowed = True

    @classmethod
    async def generate_payroll_id(cls) -> str:
        """
        Generate unique sequential payroll ID (PAY001, PAY002, etc.)

        Returns:
            str: Next available payroll ID (e.g., "PAY001")
        """
        try:
            # Find the highest existing payroll_id
            last_payroll = await cls.find(
                cls.deleted_at == None
            ).sort([("payroll_id", -1)]).limit(1).to_list()

            if not last_payroll or not last_payroll[0].payroll_id:
                # First payroll record
                return "PAY001"

            # Extract the numeric part from the last payroll_id (e.g., "PAY001" -> 1)
            last_id = last_payroll[0].payroll_id
            if last_id.startswith("PAY"):
                try:
                    last_number = int(last_id[3:])
                    next_number = last_number + 1
                except ValueError:
                    # If parsing fails, start from 1
                    next_number = 1
            else:
                next_number = 1

            # Format with leading zeros (PAY001, PAY002, ..., PAY999)
            return f"PAY{str(next_number).zfill(3)}"

        except Exception as e:
            logger.error(f"Error generating payroll_id: {str(e)}")
            # Fallback: use timestamp-based ID if sequence generation fails
            return f"PAY{datetime.now().strftime('%Y%m%d%H%M%S')[-6:]}"

    async def save(self, *args, **kwargs):
        """Override save to update updated_at timestamp"""
        self.updated_at = datetime.now()
        return await super().save(*args, **kwargs)

