@router.get("/slots")
async def list_slots(
    exporter: Exporter = Depends(get_current_exporter),
    status: Optional[str] = Query(default=None),
    upcoming_only: bool = Query(default=True),
):
    """List all procurement slots for this exporter."""

    query: dict[str, object] = {"exporter_id": str(exporter.id)}
    if status:
        query["status"] = status
    if upcoming_only:
        query["procurement_date"] = {
            "$gte": datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
        }

    slots = await ProcurementSlot.find(query).sort("procurement_date").to_list()

    result = []
    for slot in slots:
        bookings_count = await ProcurementBooking.find(
            {"slot_id": str(slot.id), "status": {"$ne": "cancelled"}}
        ).count()

        slot_time_slots = []
        for ts in slot.time_slots:
            ts_bookings = await ProcurementBooking.find(
                {
                    "slot_id": str(slot.id),
                    "time_slot_id": ts.slot_id,
                    "status": {"$ne": "cancelled"},
                }
            ).count()
            ts_data = ts.model_dump()
            ts_data["current_bookings"] = ts_bookings
            slot_time_slots.append(ts_data)

        result.append(
            {
                "id": str(slot.id),
                "procurement_date": slot.procurement_date.isoformat(),
                "location_name": slot.location_name,
                "location_address": slot.location_address,
                "crop_name": slot.crop_name,
                "variety": slot.variety,
                "expected_price_per_quintal": slot.expected_price_per_quintal,
                "min_quantity_kg": slot.min_quantity_kg,
                "max_quantity_kg": slot.max_quantity_kg,
                "status": slot.status,
                "time_slots": slot_time_slots,
                "total_bookings": bookings_count,
                "notes": slot.notes,
                "created_at": slot.created_at.isoformat(),
            }
        )

    return {"slots": result}


@router.post("/slots")
async def create_slot(
    request: CreateSlotRequest,
    exporter: Exporter = Depends(get_current_exporter),
):
    """Create a new procurement slot."""

    try:
        proc_date = datetime.fromisoformat(request.procurement_date)
    except Exception as exc:
        raise HTTPException(status_code=400, detail="Invalid date format") from exc

    if proc_date < datetime.utcnow():
        raise HTTPException(status_code=400, detail="Cannot create slots in the past")

    if request.time_slots:
        time_slots = []
        for i, ts in enumerate(request.time_slots):
            time_slots.append(
                TimeSlot(
                    slot_id=ts.get("slot_id", f"slot_{i}"),
                    label=ts.get("label", f"Slot {i + 1}"),
                    start_time=ts.get("start_time", ""),
                    end_time=ts.get("end_time", ""),
                    max_bookings=ts.get("max_bookings", 15),
                )
            )
    else:
        time_slots = [ts.model_copy(deep=True) for ts in DEFAULT_TIME_SLOTS]

    slot = ProcurementSlot(
        exporter_id=str(exporter.id),
        created_by=str(exporter.id),
        procurement_date=proc_date,
        location_name=request.location_name,
        location_address=request.location_address,
        location_lat=request.location_lat,
        location_lon=request.location_lon,
        crop_name=request.crop_name,
        variety=request.variety,
        expected_price_per_quintal=request.expected_price_per_quintal,
        min_quantity_kg=request.min_quantity_kg,
        max_quantity_kg=request.max_quantity_kg,
        time_slots=time_slots,
        notes=request.notes,
    )
    await slot.insert()

    return {
        "status": "success",
        "id": str(slot.id),
        "message": f"Procurement slot created for {proc_date.strftime('%d %b %Y')}",
    }


@router.put("/slots/{slot_id}")
async def update_slot(
    slot_id: str,
    request: CreateSlotRequest,
    exporter: Exporter = Depends(get_current_exporter),
):
