    slot.min_quantity_kg = request.min_quantity_kg
    slot.max_quantity_kg = request.max_quantity_kg
    slot.notes = request.notes
    slot.updated_at = datetime.utcnow()
    await slot.save()

    return {"status": "success"}


@router.delete("/slots/{slot_id}")
async def cancel_slot(
    slot_id: str,
    exporter: Exporter = Depends(get_current_exporter),
):
    """Cancel a procurement slot and cascade-cancel confirmed bookings."""

    try:
        slot = await ProcurementSlot.get(PydanticObjectId(slot_id))
    except Exception as exc:
        raise HTTPException(status_code=404, detail="Slot not found") from exc

    if not slot or slot.exporter_id != str(exporter.id):
        raise HTTPException(status_code=404, detail="Slot not found")

    slot.status = "cancelled"
    slot.updated_at = datetime.utcnow()
    await slot.save()

    bookings = await ProcurementBooking.find(
        {"slot_id": slot_id, "status": "confirmed"}
    ).to_list()

    for booking in bookings:
        booking.status = "cancelled"
        booking.cancellation_reason = "Slot cancelled by exporter"
        booking.updated_at = datetime.utcnow()
        await booking.save()

    return {"status": "cancelled", "bookings_cancelled": len(bookings)}


