@router.post("/bookings")
async def create_booking(
    request: CreateBookingRequest,
    exporter: Exporter = Depends(get_current_exporter),
):
    """Create a booking (from dashboard)."""

    try:
        slot = await ProcurementSlot.get(PydanticObjectId(request.slot_id))
    except Exception as exc:
        raise HTTPException(status_code=404, detail="Slot not found") from exc

    if not slot or slot.status != "open" or slot.exporter_id != str(exporter.id):
        raise HTTPException(status_code=400, detail="Slot is not available")

    try:
        farmer = await Farmer.get(PydanticObjectId(request.farmer_id))
    except Exception as exc:
        raise HTTPException(status_code=404, detail="Farmer not found") from exc

    if not farmer or str(getattr(farmer, "exporter_id", "")) != str(exporter.id):
        raise HTTPException(status_code=400, detail="Farmer is not mapped to this exporter")

    existing = await ProcurementBooking.find_one(
        {
            "slot_id": request.slot_id,
            "farmer_id": request.farmer_id,
            "status": {"$ne": "cancelled"},
        }
    )
    if existing:
        raise HTTPException(status_code=400, detail="Farmer already has a booking for this slot")

    time_slot = next((ts for ts in slot.time_slots if ts.slot_id == request.time_slot_id), None)
    if not time_slot:
        raise HTTPException(status_code=400, detail="Invalid time slot")

    current_count = await ProcurementBooking.find(
        {
            "slot_id": request.slot_id,
            "time_slot_id": request.time_slot_id,
            "status": {"$ne": "cancelled"},
        }
    ).count()
    if current_count >= time_slot.max_bookings:
        raise HTTPException(status_code=400, detail="This time slot is full")

    booking = ProcurementBooking(
        slot_id=request.slot_id,
        exporter_id=str(exporter.id),
        farmer_id=request.farmer_id,
        farmer_name=getattr(farmer, "name", ""),
        farmer_phone=getattr(farmer, "phone", ""),
        procurement_date=slot.procurement_date,
        time_slot_id=request.time_slot_id,
        time_slot_label=time_slot.label,
        crop_name=slot.crop_name,
        expected_quantity_kg=request.expected_quantity_kg,
        booked_via=request.booked_via,
        status="confirmed",
        booking_confirmation_sent=request.booked_via in {"whatsapp", "fo_portal"},
    )
    await booking.insert()

    farmer_name = getattr(farmer, "name", "Farmer")
    return {
        "status": "success",
        "id": str(booking.id),
        "message": f"Booking confirmed for {farmer_name}",
    }


