@router.get("/available/{farmer_phone}")
async def get_available_slots_for_farmer(farmer_phone: str):
    """Get available procurement slots for a farmer by phone."""

    phone = farmer_phone.strip()
    if not phone.startswith("+"):
        phone = "+91" + phone[-10:]

    farmer = await Farmer.find_one({"phone": phone})
    if not farmer:
        return {"available": False, "message": "Farmer not registered"}

    query = {
        "exporter_id": str(farmer.exporter_id),
        "status": "open",
        "procurement_date": {
            "$gte": datetime.utcnow().replace(hour=0, minute=0, second=0, microsecond=0)
        },
    }
    slots = await ProcurementSlot.find(query).sort("procurement_date").limit(10).to_list()

    if not slots:
        return {"available": False, "message": "No procurement slots available right now"}

    existing_bookings = await ProcurementBooking.find(
        {"farmer_id": str(farmer.id), "status": {"$ne": "cancelled"}}
    ).to_list()
    booked_slot_ids = {b.slot_id for b in existing_bookings}

    slots_payload = []
    for s in slots:
        time_slots_payload = []
        for ts in s.time_slots:
            current_bookings = await ProcurementBooking.find(
                {
                    "slot_id": str(s.id),
                    "time_slot_id": ts.slot_id,
                    "status": {"$ne": "cancelled"},
                }
            ).count()
            time_slots_payload.append(
                {
                    "id": ts.slot_id,
                    "label": ts.label,
                    "available": current_bookings < ts.max_bookings,
                }
            )

        slots_payload.append(
            {
                "id": str(s.id),
                "date": s.procurement_date.strftime("%d %b %Y"),
                "date_iso": s.procurement_date.isoformat(),
                "location": s.location_name,
                "crop": s.crop_name,
                "price": s.expected_price_per_quintal,
                "time_slots": time_slots_payload,
                "already_booked": str(s.id) in booked_slot_ids,
            }
        )

    return {
        "available": True,
        "farmer_name": farmer.name,
        "slots": slots_payload,
        "existing_bookings": [
            {
                "date": b.procurement_date.strftime("%d %b %Y"),
                "time": b.time_slot_label,
                "crop": b.crop_name,
                "status": b.status,
            }
            for b in existing_bookings
            if b.status != "cancelled"
        ],
    }


