router = APIRouter(prefix="/auth", tags=["auth"])

class GoogleLoginRequest(BaseModel):
    token: str

class RefreshRequest(BaseModel):
    refresh_token: str


@router.post("/google-login")
async def google_login(payload: GoogleLoginRequest):

    try:
        idinfo = id_token.verify_oauth2_token(
            payload.token,
            requests.Request(),
            settings.GOOGLE_CLIENT_ID,
        )

        email = idinfo["email"]
        name = idinfo.get("name", "")

    except Exception:
        raise HTTPException(status_code=400, detail="Invalid Google token")

    exporter = await Exporter.find_one({"email": email})

    if not exporter:
        exporter = Exporter(
            company_name=name,
            contact_person=name,
            email=email,
            phone="",
            address="",
            country="India",
            status="trial",
            subscription_id=None,
            compliance_profile_id=None
        )
        await exporter.insert()

    token_data = {"sub": str(exporter.id), "role": "exporter"}
    access_token = create_access_token(token_data)
    refresh_token = create_refresh_token(token_data)

    return {
        "access_token": access_token,
        "refresh_token": refresh_token,
        "exporter": {
            "id": str(exporter.id),
            "email": exporter.email,
            "status": exporter.status,
        }
    }


@router.post("/refresh")
async def refresh_access_token(payload: RefreshRequest):
    try:
        decoded = jwt.decode(
            payload.refresh_token,
            settings.JWT_SECRET_KEY,
            algorithms=[settings.JWT_ALGORITHM],
        )
    except JWTError:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid or expired refresh token",
        )

    if decoded.get("type") != "refresh":
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid token type",
        )

    exporter_id = decoded.get("sub")
    if not exporter_id:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid token payload",
        )

    exporter = await Exporter.get(PydanticObjectId(exporter_id))
    if not exporter:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Exporter not found",
        )

    if exporter.status == "suspended":
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="Account suspended",
        )

    new_access_token = create_access_token({"sub": str(exporter.id), "role": "exporter"})

    return {"access_token": new_access_token}

